<script lang="ts">
  import { uiLanguage, createUiTranslator } from "../i18n"
  const tr = $derived(createUiTranslator($uiLanguage))

  import { AudioLines, Mic2, Film, BookOpen, FileText, ArrowRightLeft, ListChecks, BookMarked, ArrowUpRight, Plus, Folder, Play, ChevronRight } from '@lucide/svelte';
  import Button from '../ui/Button.svelte';
  import VoiceOrb from '../playback/VoiceOrb.svelte';
  import type { OrbVariant } from '../playback/voice-orb';
  import VoiceAvatar from '../ui/VoiceAvatar.svelte';
  import type { Page, Voice, Project, Render } from '../data';
  import type { AudioFeatures, OrbAudioBands } from '../playback/playback-meter';
  let { voices, projects, recordings, ready, voiceId = 'voicestudio-dashboard', orbVariant = 'storm', orbSyncGroup, orbSuspended = false, level = 0, bands = [], playing = false, orbAudio, features: audioFeatures, onnavigate, onnew, onproject, onvoice, onplay }: {
    voices: Voice[]; projects: Project[]; recordings: Render[]; ready: boolean; onnavigate: (page: Page) => void;
    orbVariant?: OrbVariant; orbSyncGroup?: string; orbSuspended?: boolean;
    voiceId?: string; level?: number; bands?: number[]; playing?: boolean; orbAudio?: OrbAudioBands; features?: AudioFeatures;
    onnew: () => void; onproject: (project: Project) => void; onvoice: (voice: Voice) => void; onplay: (recording: Render) => void;
  } = $props();
  const savedVoices = $derived(voices.filter(voice => !voice.demo));
  const features = [
    { id: 'studio', name: 'Tekst na mowę', description: 'Napisz narrację i nadaj jej głos.', icon: AudioLines, color: '#bc94d9' },
    { id: 'voices', name: 'Twoje głosy', description: 'Klonuj, projektuj i wybieraj brzmienia.', icon: Mic2, color: '#d997ac' },
    { id: 'dubbing', name: 'Dubbing', description: 'Przygotuj nową wersję językową filmu.', icon: Film, color: '#dfaa73' },
    { id: 'audiobooks', name: 'Audiobooki', description: 'Zamień rozdziały książki w nagranie.', icon: BookOpen, color: '#7fb2b6' },
    { id: 'transcription', name: 'Mowa na tekst', description: 'Przeczytaj nagranie i pobierz napisy.', icon: FileText, color: '#acb77c' },
    { id: 'conversion', name: 'Konwersja głosu', description: 'Te same słowa w wybranym brzmieniu.', icon: ArrowRightLeft, color: '#8fbaa6' },
    { id: 'batch', name: 'Kolejka dubbingu', description: 'Pracuj z wieloma językami i zadaniami.', icon: ListChecks, color: '#a29ccd' },
    { id: 'pronunciation', name: 'Słownik wymowy', description: 'Ustal wymowę nazw i własnych słów.', icon: BookMarked, color: '#bda482' },
  ] as const;
</script>

<div class="dashboard">
  <section class="dashboard-hero"><div class="hero-copy"><div class="dashboard-eyebrow"><i class:ready></i>{tr("Twoje lokalne studio")}</div><h1>{tr("Twój głos.")}<br/><span>{tr("Twoja następna opowieść.")}</span></h1><p>{tr("Twórz narracje, pracuj z nagraniami i wracaj do swoich projektów. Wszystko w jednym miejscu.")}</p><Button size="sm" onclick={onnew}><Plus size={15}/>{tr("Nowa narracja")}</Button></div><div class="hero-art" aria-hidden="true"><VoiceOrb {voiceId} variant={orbVariant} syncGroup={orbSyncGroup} suspended={orbSuspended} size={220} {level} {bands} {playing} {orbAudio} features={audioFeatures} ring/></div></section>
  <div class="dashboard-counts"><span>{tr("Projekty lokalne:")} <b>{projects.length}</b></span><span>{tr("Zapisane nagrania:")} <b>{recordings.length}</b></span><span>{tr("Głosy silnika:")} <b>{ready ? savedVoices.length : '—'}</b></span></div>
  <section aria-label={tr("Popularne narzędzia")}><div class="dashboard-section-heading"><h2>{tr("Popularne narzędzia")}</h2><span>{tr("Od pomysłu do gotowego nagrania")}</span></div><div class="dashboard-grid">{#each features as feature}<button class="feature-tile" onclick={() => onnavigate(feature.id)} style={`--feature-color:${feature.color}`}><span class="feature-icon"><feature.icon size={22}/></span><ArrowUpRight class="feature-arrow" size={15}/><strong>{tr(feature.name)}</strong><p>{tr(feature.description)}</p></button>{/each}</div></section>
  <section><div class="dashboard-section-heading"><h2>{tr("Ostatnie projekty")}</h2><button onclick={() => onnavigate('projects')}>{tr("Wszystkie projekty")}<ChevronRight size={14}/></button></div>{#if projects.length}<div class="dashboard-projects">{#each projects.slice(0,4) as project}<button onclick={() => onproject(project)}><Folder size={20}/><span><strong>{project.name}</strong><small>{new Date(project.updated).toLocaleDateString(tr.locale)} · {project.blocks.length} {project.blocks.length === 1 ? tr("mówca") : tr("mówców")}</small></span><ArrowUpRight size={14}/></button>{/each}</div>{:else}<div class="dashboard-empty">{tr("Tutaj pojawią się zapisane projekty.")} <button onclick={onnew}>{tr("Rozpocznij pierwszą narrację")}<ArrowUpRight size={13}/></button></div>{/if}</section>
  <div class="dashboard-library"><section><div class="dashboard-section-heading"><h2>{tr("Twoje głosy")}</h2><button onclick={() => onnavigate('voices')}>{tr("Biblioteka")}<ChevronRight size={14}/></button></div>{#if savedVoices.length}<div class="dashboard-voices">{#each savedVoices.slice(0,4) as voice}<button onclick={() => onvoice(voice)}><VoiceAvatar voiceId={voice.id} name={voice.name} portraitSrc={voice.portraitSrc} size={34}/><span><strong>{voice.name}</strong><small>{tr(voice.kind)} · {tr(voice.language)}</small></span><ArrowUpRight size={14}/></button>{/each}</div>{:else}<p class="dashboard-empty">{ready ? tr("Dodaj pierwszy profil głosu w bibliotece.") : tr("Uruchom lokalny silnik, aby zobaczyć zapisane głosy.")}</p>{/if}</section><section><div class="dashboard-section-heading"><h2>{tr("Ostatnie nagrania")}</h2><button onclick={() => onnavigate('history')}>{tr("Wszystkie")}<ChevronRight size={14}/></button></div>{#if recordings.length}<div class="dashboard-voices">{#each recordings.slice(0,4) as recording}<button onclick={() => onplay(recording)}><Play size={18}/><span><strong>{recording.title}</strong><small>{recording.voice}</small></span><ArrowUpRight size={14}/></button>{/each}</div>{:else}<p class="dashboard-empty">{tr("Gotowe i wczytane nagrania pojawią się tutaj.")}</p>{/if}</section></div>
</div>

<style>
